def transform_voronoi_2s(grid):
    """Template of 1s at positions where |dr| == |dc| around 2s"""
    R, C = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # All 2 positions
    twos = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == 2]

    for r in range(R):
        for c in range(C):
            # Check if this position is on the "Voronoi" pattern of any 2
            for tr, tc in twos:
                dr, dc = abs(r - tr), abs(c - tc)
                # Pattern: |dr| == |dc| AND dr > 0 (excluding the 2 itself)
                if dr == dc and dr > 0:
                    if grid[r][c] == 3:
                        result[r][c] = 1
                    break  # Only first 2 pattern applies

    return result

