def transform_halo(grid):
    """Apply 3x3 halo: change 3s to 1s at odd Manhattan distances from 2s"""
    R, C = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all 2s
    twos = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == 2]

    for r in range(R):
        for c in range(C):
            # Check if this cell is within 3x3 of any 2
            closest_2 = None
            min_dist = float('inf')
            for tr, tc in twos:
                dist = abs(r - tr) + abs(c - tc)
                if dist <= 3 and dist < min_dist:
                    min_dist = dist
                    closest_2 = (tr, tc)

            # If it's an odd distance (1 or 3) from the nearest 2
            if min_dist in [1, 3] and closest_2:
                if grid[r][c] == 3:
                    result[r][c] = 1
                elif grid[r][c] == 0:
                    result[r][c] = 1

    return result

